#!/usr/bin/env python3
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT/'src'/'CE.Tools.Civil3D'

def rep(file, old, new, count=1):
 p=SRC/file; t=p.read_text(encoding='utf-8'); n=t.count(old)
 if n < count: raise SystemExit(f'{file}: marker missing ({n}<{count})\n{old[:200]}')
 t=t.replace(old,new,count); p.write_text(t,encoding='utf-8')

